import logos from "@/data/partners.json";

/** File name in public/partners (generated by `npm run partners` from assets/partners). */
export type PartnerLogo = keyof typeof logos;

export interface Partner {
  logo: PartnerLogo;
  nameAr: string;
  nameEn: string;
  /** Optical correction for unusually heavy or light artwork (1 = none). */
  scale?: number;
}

// Order of appearance in the slider; the first half fills the top row.
export const partners: Partner[] = [
  { logo: "air-arabia", nameAr: "العربية للطيران", nameEn: "Air Arabia" },
  { logo: "ajet", nameAr: "أجيت", nameEn: "AJet" },
  { logo: "emirates", nameAr: "طيران الإمارات", nameEn: "Emirates" },
  { logo: "flydubai", nameAr: "فلاي دبي", nameEn: "flydubai" },
  { logo: "fly-baghdad", nameAr: "فلاي بغداد", nameEn: "Fly Baghdad", scale: 1.1 },
  { logo: "fly-cham", nameAr: "فلاي شام", nameEn: "Fly Cham" },
  { logo: "qatar-airways", nameAr: "الخطوط الجوية القطرية", nameEn: "Qatar Airways" },
  { logo: "sabre", nameAr: "سابر لأنظمة الحجز", nameEn: "Sabre GDS", scale: 0.88 },
  { logo: "salamair", nameAr: "طيران السلام", nameEn: "SalamAir" },
  { logo: "turkish-airlines", nameAr: "الخطوط الجوية التركية", nameEn: "Turkish Airlines", scale: 0.94 },
  { logo: "royal-jordanian", nameAr: "الملكية الأردنية", nameEn: "Royal Jordanian" },
  { logo: "ur-airlines", nameAr: "أور للطيران", nameEn: "Ur Airlines" },
  { logo: "global-aviation", nameAr: "جلوبال أفييشن", nameEn: "Global Aviation" },
];

// Every card is 20:9. Logos share a target *area* instead of a width or a height, so a
// compact emblem and a long wordmark carry the same visual weight. Units are fractions
// of the card width.
const CARD_HEIGHT = 9 / 20;
const MAX_WIDTH = 0.7;
const MAX_HEIGHT = CARD_HEIGHT * 0.6;
const AREA = 0.112;

/** Rendered logo width as a percentage of its card. */
export function partnerLogoWidth({ logo, scale = 1 }: Partner) {
  const { width, height } = logos[logo];
  const ratio = width / height;
  const w = Math.min(MAX_WIDTH, Math.sqrt(AREA * ratio) * scale, MAX_HEIGHT * ratio);
  return `${(w * 100).toFixed(2)}%`;
}

export const partnerLogoSize = (logo: PartnerLogo) => logos[logo];
